import type { Metadata } from "next";
import { siteConfig } from "@/config/site";

/** Site origin without a trailing slash, e.g. "https://quickrestorationny.com". */
export const siteOrigin = siteConfig.url.replace(/\/+$/, "");

/** Path shared by every page's social card (generated by app/opengraph-image.tsx). */
export const OG_IMAGE_PATH = "/opengraph-image";

/** "/services" -> "https://quickrestorationny.com/services". Absolute URLs pass through unchanged. */
export function absoluteUrl(path = "/") {
  if (/^https?:\/\//i.test(path)) return path;
  return `${siteOrigin}${path.startsWith("/") ? path : `/${path}`}`;
}

/** "(631) 555-0199" -> "+16315550199" (E.164, assumes a US number when 10 digits). */
export function phoneE164(display: string) {
  const digits = display.replace(/\D/g, "");
  return `+${digits.length === 10 ? `1${digits}` : digits}`;
}

interface BuildMetadataInput {
  /** Page title; the root layout appends " | Quick Restoration". */
  title: string;
  description: string;
  /** Route path such as "/privacy". Becomes the canonical URL and og:url. */
  path: string;
  /** Root-relative or absolute image. Defaults to the site-wide Open Graph image. */
  image?: string;
  /** Set to false to keep a page out of search results. */
  index?: boolean;
}

/**
 * Consistent per-page metadata: canonical, Open Graph and Twitter cards all
 * pointing at the same absolute URLs. Pages can spread extra fields on top.
 */
export function buildMetadata({ title, description, path, image, index = true }: BuildMetadataInput): Metadata {
  const url = absoluteUrl(path);
  const imageUrl = absoluteUrl(image ?? OG_IMAGE_PATH);
  const socialTitle = `${title} | ${siteConfig.name}`;

  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_US",
      siteName: siteConfig.name,
      url,
      title: socialTitle,
      description,
      images: [{ url: imageUrl, width: 1200, height: 630, alt: `${siteConfig.name} - ${siteConfig.tagline}` }],
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images: [imageUrl],
    },
    robots: index ? { index: true, follow: true } : { index: false, follow: false },
  };
}
